BEGIN;
CREATE TABLE IF NOT EXISTS telemetry_imports (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, player_id BIGINT NOT NULL, source_kind TEXT NOT NULL CHECK(source_kind IN('game_api','replay','video','team','wearable')), external_id TEXT NOT NULL, checksum TEXT NOT NULL, game_patch TEXT NOT NULL, terms_version TEXT NOT NULL, consent_record_id TEXT NOT NULL, guardian_consent_record_id TEXT, imported_by BIGINT, imported_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tenant_id,source_kind,external_id,checksum));
CREATE TABLE IF NOT EXISTS coaching_interventions (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, player_id BIGINT NOT NULL, telemetry_import_id BIGINT REFERENCES telemetry_imports(id), state TEXT NOT NULL DEFAULT 'ingested', metric JSONB, recommendation JSONB NOT NULL DEFAULT '{}', uncertainty JSONB NOT NULL DEFAULT '{}', consent_active BOOLEAN NOT NULL DEFAULT TRUE, version INTEGER NOT NULL DEFAULT 1, created_by BIGINT, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS coaching_audit (id BIGSERIAL PRIMARY KEY, tenant_id TEXT NOT NULL, intervention_id BIGINT REFERENCES coaching_interventions(id), actor_id BIGINT, action TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS coaching_player_timeline_idx ON coaching_interventions(tenant_id,player_id,updated_at DESC);
COMMIT;
